  1	/* ============================================================
  2	   views/project-detail-helpers.js — Project Detail: pure helpers
  3	   Sub-module of views/project-detail.js (WP-004 decomposition).
  4	   Depends on: escapeHtml (utils.js)
  5	
  6	   Exports (on globalThis via bottom of this file):
  7	     extractSynopsis, STAGE_ABBREV, buildPipelineTrack,
  8	     buildRunBadges, _findScrollAnchor,
  9	     _snapshotProjectState, _diffProjectState
 10	   ============================================================ */
 11	
 12	/* ----------------------------------------------------------
 13	   4b. View: Plan Document
 14	   ---------------------------------------------------------- */
 15	function extractSynopsis(markdown) {
 16	  var match = markdown.match(/## Summary\s*\n([\s\S]*?)(?=\n## |\n---|\s*$)/);
 17	  return match ? match[1].trim() : null;
 18	}
 19	
 20	/* ----------------------------------------------------------
 21	   4c. View: Project Detail — display helpers
 22	   ---------------------------------------------------------- */
 23	
 24	/**
 25	 * Display abbreviations for pipeline stage type strings.
 26	 *
 27	 * Maps each ledger pipeline type to the two- or three-character label shown
 28	 * in the pipeline-track badge column of the project-detail table.
 29	 * `buildPipelineTrack` falls back to `stage.type.slice(0, 3).toUpperCase()`
 30	 * for any type that is absent from this map, so unknown types render
 31	 * gracefully but without a meaningful abbreviation.
 32	 *
 33	 * **Maintenance contract:** whenever a new pipeline type is added to the
 34	 * ledger (e.g., in `PIPELINE_TYPES` on the server), add a corresponding
 35	 * entry here.  Omitting a new type will not cause a runtime error, but the
 36	 * badge label in the GUI will be a raw three-character slice of the type
 37	 * string instead of a human-readable abbreviation.
 38	 */
 39	var STAGE_ABBREV = {
 40	  'implementation':     'DEV',
 41	  'qa':                 'QA',
 42	  'security-audit':     'SEC',
 43	  'code-review':        'REV',
 44	  'release-engineering':'REL',
 45	  'documentation':      'DOC'
 46	};
 47	
 48	function buildPipelineTrack(overviewEntry) {
 49	  if (!overviewEntry || !overviewEntry.pipeline_stages || !overviewEntry.pipeline_stages.length) {
 50	    return '—';
 51	  }
 52	  var badges = overviewEntry.pipeline_stages.map(function (stage) {
 53	    var abbrev = STAGE_ABBREV[stage.type] || stage.type.slice(0, 3).toUpperCase();
 54	    var statusClass = 'stage-pending';
 55	    if (stage.status === 'in-progress') statusClass = 'stage-in-progress';
 56	    else if (stage.status === 'pass')        statusClass = 'stage-pass';
 57	    else if (stage.status === 'fail')        statusClass = 'stage-fail';
 58	    var tooltip = escapeHtml(stage.type) + ' — ' + escapeHtml(stage.agent);
 59	    if (stage.rework_count > 0) tooltip += ' (rework: ' + stage.rework_count + ')';
 60	    var reworkBadge = stage.rework_count > 0
 61	      ? '<span class="rework-indicator" title="Rework count: ' + stage.rework_count + '">' + stage.rework_count + '</span>'
 62	      : '';
 63	    return '<span class="stage-badge ' + statusClass + '" title="' + tooltip + '">' +
 64	      escapeHtml(abbrev) +
 65	      reworkBadge +
 66	    '</span>';
 67	  }).join('');
 68	  return '<div class="pipeline-track">' + badges + '</div>';
 69	}
 70	
 71	function buildRunBadges(item, isActive) {
 72	  var badges = '';
 73	  if (isActive) {
 74	    badges += UI.badge('in-progress', 'Running');
 75	  }
 76	  if (item && item.is_dry_run) {
 77	    badges += UI.badge('dry-run', 'Dry Run');
 78	  }
 79	  return badges;
 80	}
 81	
 82	/**
 83	 * Walk up the DOM from el to find the nearest scrollable ancestor.
 84	 *
 85	 * Falls back to document.documentElement when no scrollable ancestor is found.
 86	 * The optional _getStyle parameter allows injecting a custom style resolver for
 87	 * test environments (jsdom) where window.getComputedStyle always returns empty
 88	 * objects.
 89	 *
 90	 * @param {Element}  el          - Starting element.
 91	 * @param {Function} [_getStyle] - Style resolver; defaults to window.getComputedStyle.
 92	 *   Receives a single Element and returns an object with an overflowY property.
 93	 *   Falls back to () => ({}) when window.getComputedStyle is unavailable.
 94	 * @returns {Element} The nearest scrollable ancestor, or document.documentElement.
 95	 */
 96	function _findScrollAnchor(el, _getStyle) {
 97	  var getStyle = typeof _getStyle === 'function'
 98	    ? _getStyle
 99	    : (window.getComputedStyle || function () { return {}; });
100	  var cur = el;

  1	/* ============================================================
  2	   views/project-detail-modal.js — Project Detail: Reset Project modal
  3	   Sub-module of views/project-detail.js (WP-004 decomposition).
  4	   Depends on: project-detail-helpers.js (must be loaded first),
  5	               API (api-client.js), escapeHtml (utils.js),
  6	               statusBadge (components.js), UI (components.js)
  7	
  8	   Exports:
  9	     PIPELINE_STAGES, showResetModal
 10	   ============================================================ */
 11	
 12	/* ----------------------------------------------------------
 13	   4c-ii. Reset Project Modal
 14	   ---------------------------------------------------------- */
 15	var PIPELINE_STAGES = ['implementation', 'qa', 'security-audit', 'code-review', 'release-engineering', 'documentation'];
 16	
 17	function showResetModal(repo, slug, diagnosis, options) {
 18	  // Remove any existing modal
 19	  var existing = document.getElementById('reset-modal-overlay');
 20	  if (existing) existing.remove();
 21	
 22	  var wps = diagnosis.work_packages || [];
 23	
 24	  // Build state: per-WP action + criteria checkbox
 25	  var state = {};
 26	  wps.forEach(function (wp) {
 27	    state[wp.work_package_id] = {
