117	/**
118	 * Extract a comparable state snapshot from API response objects.
119	 *
120	 * @param {object} project      - Response from API.getProject()
121	 * @param {Array|null} overviewResult - Response from API.getWorkPackageOverview() (may be null)
122	 * @returns {{
123	 *   status: string,
124	 *   last_updated: string,
125	 *   synthesis_generated: boolean,
126	 *   wpStatuses: Object.<string, { status: string, pipelineStages: Array }>,
127	 *   health: null | { work_packages_needing_reset: number }
128	 * }}
129	 */
130	function _snapshotProjectState(project, overviewResult) {
131	  var meta = (project && project.meta) || {};
132	  var wps  = (project && project.work_packages) || [];
133	
134	  // Build per-WP status map
135	  var wpStatuses = {};
136	  wps.forEach(function (wp) {
137	    if (!wp || !wp.work_package_id) return;
138	    wpStatuses[wp.work_package_id] = {
139	      status: wp.status || '',
140	      pipelineStages: [],
141	    };
142	  });
143	
144	  // Enrich with pipeline stage data from overview
145	  if (Array.isArray(overviewResult)) {
146	    overviewResult.forEach(function (entry) {
147	      if (!entry || !entry.work_package_id) return;
148	      var id = entry.work_package_id;
149	      var stages = Array.isArray(entry.pipeline_stages)
150	        ? entry.pipeline_stages.map(function (s) {
151	            return {
152	              type:         s.type        || '',
153	              status:       s.status      || '',
154	              agent:        s.agent       || '',
155	              rework_count: s.rework_count || 0,
156	            };
157	          })
158	        : [];
159	      if (wpStatuses[id]) {
160	        wpStatuses[id].pipelineStages = stages;
161	      } else {
162	        // Overview entry present without a matching WP in the main list.
163	        wpStatuses[id] = { status: '', pipelineStages: stages };
164	      }
165	    });
166	  }
167	
168	  return {
169	    status:               meta.status              || '',
170	    last_updated:         meta.last_updated         || '',
171	    synthesis_generated:  !!(project && project.synthesis_generated),
172	    wpStatuses:           wpStatuses,
173	    health:               null,  // populated asynchronously via getProjectHealth()
174	  };
175	}
176	
177	/**
178	 * Compare two project-state snapshots and classify the difference.
179	 *
180	 * Structural changes (require full re-render):
181	 *   - The number of work packages differs between snapshots.
182	 *   - The project transitioned to COMPLETE or ARCHIVED status.
183	 *
184	 * Data-only changes (patchable in-place):
185	 *   - Status badge changed but is not a structural transition.
186	 *   - Any per-WP status or pipeline-stage changed.
187	 *   - synthesis_generated flipped.
188	 *   - health changed (including null → value transitions).
189	 *   - last_updated changed.
190	 *
191	 * NOTE — per-WP iteration order: per-WP status/pipeline changes are detected by
192	 * iterating over `next.wpStatuses` keys only. A WP present in `prev` but absent
193	 * from `next` is therefore not tracked per-field; the structural `wpCount` check
194	 * handles that case before per-WP diffing is reached. In practice, a missing WP
195	 * always triggers a structural re-render, so the per-field gap is intentional.
196	 *
197	 * @param {object} prev - Previous snapshot from _snapshotProjectState().
198	 *   Must be non-null; passing null will throw on Object.keys(prev.wpStatuses).
199	 *   Callers must initialise pollStateRef[0] with a real snapshot before
200	 *   registering the poll interval — the 5s setInterval delay ensures the
201	 *   first tick cannot fire before that assignment completes.
202	 * @param {object} next - Current  snapshot from _snapshotProjectState().
203	 * @returns {{ type: 'none'|'data'|'structural', changes: object }}
204	 */
205	function _diffProjectState(prev, next) {
206	  var changes = {};
207	  var changeType = 'none';
208	
209	  function markData(key, from, to) {
210	    changes[key] = { from: from, to: to };
211	    if (changeType === 'none') changeType = 'data';
212	  }
213	
214	  function markStructural(key, from, to) {
215	    changes[key] = { from: from, to: to };
216	    changeType = 'structural';
217	  }
218	
219	  // ── WP count ────────────────────────────────────────────────────────
220	  var prevIds = Object.keys(prev.wpStatuses || {});
221	  var nextIds = Object.keys(next.wpStatuses || {});
222	  if (prevIds.length !== nextIds.length) {
223	    markStructural('wpCount', prevIds.length, nextIds.length);
224	  }
225	
226	  // ── Project status ──────────────────────────────────────────────────
227	  if (prev.status !== next.status) {
228	    var isStructuralStatus = next.status === 'COMPLETE' || next.status === 'ARCHIVED';
229	    if (isStructuralStatus) {
230	      markStructural('status', prev.status, next.status);
231	    } else {
232	      markData('status', prev.status, next.status);
233	    }
234	  }
235	
236	  // ── Per-WP statuses and pipeline stages ─────────────────────────────
237	  nextIds.forEach(function (id) {
238	    var prevWp = (prev.wpStatuses || {})[id] || { status: '', pipelineStages: [] };
239	    var nextWp = (next.wpStatuses || {})[id] || { status: '', pipelineStages: [] };
240	
241	    if (prevWp.status !== nextWp.status) {
242	      markData('wp.' + id + '.status', prevWp.status, nextWp.status);
243	    }
244	
245	    // Compare pipeline stages as JSON strings (simple deep-equal for flat objects)
246	    var prevStagesStr = JSON.stringify(prevWp.pipelineStages || []);
247	    var nextStagesStr = JSON.stringify(nextWp.pipelineStages || []);
248	    if (prevStagesStr !== nextStagesStr) {
249	      markData('wp.' + id + '.pipelineStages', prevWp.pipelineStages, nextWp.pipelineStages);
250	    }

251	  });
252	
253	  // ── synthesis_generated ─────────────────────────────────────────────
254	  if (!!prev.synthesis_generated !== !!next.synthesis_generated) {
255	    markData('synthesis_generated', prev.synthesis_generated, next.synthesis_generated);
256	  }
257	
258	  // ── health ──────────────────────────────────────────────────────────
259	  // null-to-value (or any value change) is data-only
260	  var prevHealthStr = JSON.stringify(prev.health || null);
261	  var nextHealthStr = JSON.stringify(next.health || null);
262	  if (prevHealthStr !== nextHealthStr) {
263	    markData('health', prev.health, next.health);
264	  }
265	
266	  // ── last_updated ────────────────────────────────────────────────────
267	  if (prev.last_updated !== next.last_updated) {
268	    markData('last_updated', prev.last_updated, next.last_updated);
269	  }
270	
271	  return { type: changeType, changes: changes };
272	}
